706	func validDeviceStatus(status string) bool {
707		switch status {
708		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
709			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
710			DeviceAwaitingRollback, DeviceRollingBack,
711			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
712			return true
713		default:
714			return false
715		}
716	}
