718	// isRollbackTerminal 判断状态是否属于回滚相关终态。
719	func isRollbackTerminal(status string) bool {
720		switch status {
721		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
722			return true
723		default:
724			return false
725		}
726	}
