728	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
729	func isRollbackFlowStatus(status string) bool {
730		switch status {
731		case DeviceAwaitingRollback, DeviceRollingBack,
732			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
733			return true
734		default:
735			return false
736		}
737	}
