739	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
740	func validateRollbackDisk(campaignID string, dd diskDev) error {
741		bad := func(msg string) error {
742			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
743		}
744		rb := dd.Rollback
745		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
746		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
747		if dd.RollbackTarget != "" && !dd.Download.Claimed {
748			return bad("rollback target locked before download claim")
749		}
750		// 已领取下载且尚无下载结果，或已有成功下载结果：回滚目标必须已锁定，
751		// 字段缺失与空串按同一种损坏处理。这项要求不因设备进入安装阶段或
752		// 活动已结束而取消——否则安装失败后会留下没有明确恢复版本的回滚待办。
753		// 不能用当前影子版本、活动目标版本或允许升级列表替代丢失的目标。
754		// 首次领取前复查版本不兼容、直接在下载阶段失败的设备（下载已有失败
755		// 结果）允许没有目标：这种失败不进入安装或回滚。
756		if dd.RollbackTarget == "" && dd.Download.Claimed &&
757			(!dd.Download.HasResult || dd.Download.Success) {
758			return bad("missing locked rollback target")
759		}
760		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
761		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
762			return bad("rollback status without locked target")
763		}
764		// 回滚流程的唯一入口是“已接受本次安装的失败结果”：等待回滚、正在回滚
765		// 以及回滚成功/失败/超时的设备，都必须能从本设备在本活动中已经接受的
766		// 安装结果确认安装失败。安装尚未领取、已领取但没有结果，或安装结果为
767		// 成功，都不能支持任何回滚状态；即使回滚目标非空、操作标识合法、回滚
768		// 结果与历史一致或活动已结束，也必须核对这一前提。当前版本恰好等于旧
769		// 版本、下载失败以及其他设备或其他活动的失败记录都不能代替本次安装失败
770		// （这里只看本设备本活动保存的安装操作结果本身）。
771		installFailed := dd.Install.HasResult && !dd.Install.Success
772		if isRollbackFlowStatus(dd.Status) && !installFailed {
773			return bad("rollback state without accepted install failure")
774		}
775		switch dd.Status {
776		case DeviceAwaitingRollback:
777			// 已接受安装失败、回滚尚未领取：回滚无结果。
778			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
779				return bad("awaiting rollback state mismatch")
780			}
781		case DeviceRollingBack:
782			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
783				return bad("rolling back state mismatch")
784			}
785		case DeviceRollbackSucceeded:
786			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
787				return bad("rollback succeeded without success result")
788			}
789			if rb.ResultVersion != dd.RollbackTarget {
790				return bad("rollback version mismatch")
791			}
792			if _, ok := decodeObject(rb.ResultConfig); !ok {
793				return bad("rollback config invalid")
794			}
795		case DeviceRollbackFailed:
796			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
797				return bad("rollback failed without failure result")
798			}
799		case DeviceRollbackTimeout:
800			if dd.Phase != StageRollback {
801				return bad("rollback timeout phase mismatch")
802			}
803			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
804			if rb.HasResult {
805				return bad("rollback timeout with result")
806			}
807		default:
808			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
809			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
810			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
811			if dd.Install.HasResult && !dd.Install.Success {
812				return bad("install failure without rollback state")
813			}
814			if rb.Claimed || rb.HasResult {
815				return bad("rollback progressed without install failure")
816			}
817		}
818		return nil
819	}
820

