5		"time"
6	)
7	
8	// setOpClaimedAt 直接改写设备某阶段（download/install/rollback）首次领取的时间
9	// （RFC3339 字符串，可用不同时区写法），用来构造按正常流程无法产生的窗口外
10	// 首次领取记录。
11	func setOpClaimedAt(t *testing.T, dir, campaignID, deviceID, op, claimedAt string) []byte {
12		t.Helper()
13		return rewriteStoreBytes(t, dir, func(doc map[string]any) {
14			d := campaignDeviceDoc(doc, campaignID, deviceID)
15			if d == nil {
16				t.Fatalf("device %s missing in campaign %s", deviceID, campaignID)
17			}
18			o := d[op].(map[string]any)
19			o["claimed"] = true
20			o["claimedAt"] = claimedAt
21		})
22	}
23	
24	// setupDownloading 构造单设备活动：设备 12:10 首次领取下载、尚未完成，
25	// 关闭后返回存储目录。窗口 12:00–13:00，截止 14:00。
26	func setupDownloading(t *testing.T) (*Store, string, CampaignSpec) {
27		t.Helper()
28		s := setupUpgrade(t, "d1")
29		spec := upSpec()
