43	// TestRestoreClaimWindowRefused 保护打开存储时的维护窗口核对：每个已领取的
44	// 下载/安装/回滚操作，其首次领取时间必须落在活动保存的原维护窗口
45	// [start, end) 内；窗口外的首次领取必须使整个存储拒绝打开且内容不变，
46	// 活动是否结束、操作后来成功/失败/超时都不能掩盖。
47	func TestRestoreClaimWindowRefused(t *testing.T) {
