56		// 窗口不包含结束时刻：恰好 13:00 首次领取即窗口外。
57		t.Run("download claimed exactly at window end", func(t *testing.T) {
58			s := setupUpgrade(t, "d1")
59			spec := upSpec()
60			spec.Devices = []string{"d1"}
61			createCampaign(t, s, spec)
62			bringOnline(t, s, "d1")
63			if _, err := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute)); err != nil {
64				t.Fatalf("claim: %v", err)
65			}
66			// 推进时间基线，使被改写的领取时间不触发其他时间核对。
67			if err := s.AdvanceCampaign(spec.ID, upBase.Add(90*time.Minute)); err != nil {
68				t.Fatal(err)
69			}
70			dir := s.dir
71			s.Close()
72			original := setOpClaimedAt(t, dir, spec.ID, "d1", "download", "2026-10-02T13:00:00Z")
73			assertReopenCorrupt(t, dir, original)
74		})
75	
76		// 晚于窗口结束的首次领取同样拒绝。
77		t.Run("download claimed after window end", func(t *testing.T) {
78			s := setupUpgrade(t, "d1")
79			spec := upSpec()
80			spec.Devices = []string{"d1"}
81			createCampaign(t, s, spec)
82			bringOnline(t, s, "d1")
83			if _, err := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute)); err != nil {
84				t.Fatalf("claim: %v", err)
85			}
86			if err := s.AdvanceCampaign(spec.ID, upBase.Add(100*time.Minute)); err != nil {
87				t.Fatal(err)
88			}
89			dir := s.dir
90			s.Close()
91			original := setOpClaimedAt(t, dir, spec.ID, "d1", "download", "2026-10-02T13:30:00Z")
92			assertReopenCorrupt(t, dir, original)
93		})
94	
95		// 安装的首次领取也受同一窗口约束。
96		t.Run("install claimed outside window", func(t *testing.T) {
97			s := setupUpgrade(t, "d1")
98			spec := upSpec()
99			spec.Devices = []string{"d1"}
100			createCampaign(t, s, spec)
101			bringOnline(t, s, "d1")
102			dl, _ := s.Claim(spec.ID, "d1", upBase)
103			if err := s.SubmitResult(OperationResult{
104				CampaignID: spec.ID, DeviceID: "d1", OperationID: dl.ID,
105				At: upBase.Add(time.Minute), Success: true,
106			}); err != nil {
107				t.Fatal(err)
108			}
109			if _, err := s.Claim(spec.ID, "d1", upBase.Add(2*time.Minute)); err != nil {
110				t.Fatalf("claim install: %v", err)
111			}
112			if err := s.AdvanceCampaign(spec.ID, upBase.Add(100*time.Minute)); err != nil {
113				t.Fatal(err)
114			}
115			dir := s.dir
116			s.Close()
117			original := setOpClaimedAt(t, dir, spec.ID, "d1", "install", "2026-10-02T13:20:00Z")
118			assertReopenCorrupt(t, dir, original)
119		})
120	
121		// 回滚的首次领取也受同一窗口约束。
122		t.Run("rollback claimed outside window", func(t *testing.T) {
123			s := setupUpgrade(t, "d1")
124			spec := upSpec()
125			spec.Devices = []string{"d1"}
