139				At: upBase.Add(3 * time.Minute), Success: false, Reason: "install boom",
140			}); err != nil {
141				t.Fatal(err)
142			}
143			rb, err := s.Claim(spec.ID, "d1", upBase.Add(10*time.Minute))
144			if err != nil || rb == nil || rb.Kind != StageRollback {
