12	// 以下结构仅用于在测试中拼装存储文件，字段与磁盘格式对应。
13	type fixAudit struct {
14		Operator  string          `json:"operator"`
15		Time      string          `json:"time"`
16		Revision  uint64          `json:"revision"`
17		RequestID string          `json:"requestId,omitempty"`
18		Before    json.RawMessage `json:"before"`
19		After     json.RawMessage `json:"after"`
20	}
21	
22	type fixState struct {
23		Version        string            `json:"version"`
24		Online         bool              `json:"online"`
25		Revision       uint64            `json:"revision"`
26		Desired        any               `json:"desired"`
27		Reported       any               `json:"reported"`
28		LastSeq        uint64            `json:"lastSeq,omitempty"`
29		LastReportTime string            `json:"lastReportTime,omitempty"`
30		DiffSince      map[string]string `json:"diffSince,omitempty"`
31		Audit          []fixAudit        `json:"audit,omitempty"`
32	}
33	
34	type fixStore struct {
35		Format  int                 `json:"format"`
36		Devices map[string]fixState `json:"devices"`
37	}
38	
39	// writeFixStore 写入一份拼装存储，返回目录与写入的原始字节。
40	func writeFixStore(t *testing.T, doc fixStore) (string, []byte) {
41		t.Helper()
42		data, err := json.Marshal(doc)
43		if err != nil {
44			t.Fatal(err)
45		}
46		dir := t.TempDir()
47		if err := os.WriteFile(filepath.Join(dir, storeFileName), data, 0o644); err != nil {
48			t.Fatal(err)
49		}
50		return dir, data
51	}
52	
53	func twoAuditDoc() fixStore {
54		return fixStore{Format: 1, Devices: map[string]fixState{
55			"dev-1": {
56				Version:   "1.0",
57				Revision:  2,
58				Desired:   json.RawMessage(`{"a":2}`),
59				Reported:  json.RawMessage(`{}`),
60				DiffSince: map[string]string{"/a": "2026-10-02T12:00:00Z"},
61				Audit: []fixAudit{
62					{Operator: "alice", Time: "2026-10-02T12:00:00Z", Revision: 1, Before: json.RawMessage(`{}`), After: json.RawMessage(`{"a":1}`)},
63					{Operator: "bob", Time: "2026-10-02T12:01:00Z", Revision: 2, Before: json.RawMessage(`{"a":1}`), After: json.RawMessage(`{"a":2}`)},
64				},
65			},
66		}}
67	}
68	
69	// 正常的两次修改历史：修订号 1、2 衔接，末条修改后等于当前期望配置。
70	func TestRestoreAuditChainAccepted(t *testing.T) {
71		dir, _ := writeFixStore(t, twoAuditDoc())
72		s, err := Open(dir)
73		if err != nil {
74			t.Fatalf("valid audit chain must open: %v", err)
75		}
76		defer s.Close()
77		v, err := s.Get("dev-1")
78		if err != nil {
79			t.Fatal(err)
80		}
81		if v.Revision != 2 || string(v.Desired) != `{"a":2}` {
82			t.Fatalf("restored view: %+v", v)
83		}
84		// Get 与 Audit 保留已有内容和顺序
85		recs, err := s.Audit("dev-1")
86		if err != nil || len(recs) != 2 {
87			t.Fatalf("restored audit: %v %v", recs, err)
88		}
89		if recs[0].Revision != 1 || recs[1].Revision != 2 ||
90			recs[0].Operator != "alice" || recs[1].Operator != "bob" {
91			t.Fatalf("audit content/order changed: %+v", recs)
92		}
93	}
94	
95	// 从未修改过期望配置的设备：修订号 0、空审计、空对象期望配置。
96	// 设备已经上报其他配置或版本不影响这一判断。
97	func TestRestoreZeroRevisionAccepted(t *testing.T) {
98		dir, _ := writeFixStore(t, fixStore{Format: 1, Devices: map[string]fixState{
99			"dev-1": {
100				Version:        "1.1",
101				Online:         true,
102				Revision:       0,
103				Desired:        json.RawMessage(`{}`),
104				Reported:       json.RawMessage(`{"cpu":80}`),
105				LastSeq:        7,
106				LastReportTime: "2026-10-02T12:00:00Z",
107				DiffSince:      map[string]string{"/cpu": "2026-10-02T12:00:00Z"},
108			},
109		}})
110		s, err := Open(dir)
111		if err != nil {
112			t.Fatalf("reported config must not affect revision-zero device: %v", err)
113		}
114		defer s.Close()
115		v, _ := s.Get("dev-1")
116		if v.Revision != 0 || string(v.Desired) != "{}" || v.LastSeq != 7 || v.Version != "1.1" {
117			t.Fatalf("restored view: %+v", v)
118		}
119		if recs, _ := s.Audit("dev-1"); len(recs) != 0 {
120			t.Fatalf("unexpected audit: %+v", recs)
121		}
122	}
123	
124	// 配置比较沿用 JSON 语义：空白与对象字段顺序无关，1 与 1.0 相等；
125	// 记录只按修订号衔接，不要求操作时间严格递增。
126	func TestRestoreAuditChainSemanticEquality(t *testing.T) {
127		dir, _ := writeFixStore(t, fixStore{Format: 1, Devices: map[string]fixState{
128			"dev-1": {
129				Version:   "1.0",
130				Revision:  2,
131				Desired:   json.RawMessage(`{ "a": 1.0 }`),
132				Reported:  json.RawMessage(`{}`),
133				DiffSince: map[string]string{"/a": "2026-10-02T12:00:00Z"},
134				Audit: []fixAudit{
135					// 时间晚于第二条；after 用 1 与期望中的 1.0 按数值比较
