			d := doc.Devices["dev-1"]
			d.Audit = d.Audit[1:]
			doc.Devices["dev-1"] = d
		},
		// 修订号断开：1 之后直接是 3
		"revision gap": func(doc fixStore) {
			d := doc.Devices["dev-1"]
